//! A relationship object of six thousand octets is compared and not traversed.

use andromeda_test_suite::{
    attribute_matcher::any_attribute,
    broker,
    entity_matcher::has_attribute,
    identity_matcher::has_id,
    namespace::Namespace,
    nth::nth,
    outcome::Done,
};
use googletest::prelude::*;
use ngsi_ld::{
    http::headers::Accept,
    model::{Entity, NgsiLdMediaType},
    query::{Join, Locality, q},
};

/// Pins: A Relationship whose object is a URN of over 6,000 octets reads back unchanged, an equality on it selects
/// its source and an inequality excludes it, and a hop through it with join inline reaches nothing while the hop
/// through a local target selects that source
/// Clause: Table 5.2.6-1, 4.6.2, 4.9, 4.5.23
#[gtest]
#[tokio::test]
async fn n_ent_cre_9017_a_relationship_object_of_six_thousand_octets_is_compared_and_not_traversed() -> Result<()> {
    let namespace = Namespace::fresh();
    let broker = broker::front()?;
    let long_reference_target_id = namespace.urn("LongReference", "target")?;
    let long_reference_type = namespace.entity_type("LongReference")?;
    let long_reference_long_source_id = namespace.urn("LongReference", "long-source")?;
    let stop_zzibf4kcacb47hcyc8qc7zsg9yhlb6j13me23r7t_id = namespace.urn("Stop", "")?;
    let long_reference_short_source_id = namespace.urn("LongReference", "short-source")?;
    let long_reference_target = Entity::builder()
        .id(long_reference_target_id.clone())
        .entity_type(long_reference_type.clone())
        .property("name", "x")
        .build()?;
    broker.entities().create(&long_reference_target).send().await?.done()?;
    let long_reference_long_source = Entity::builder()
        .id(long_reference_long_source_id.clone())
        .entity_type(long_reference_type.clone())
        .relationship("link", stop_zzibf4kcacb47hcyc8qc7zsg9yhlb6j13me23r7t_id.clone())
        .build()?;
    broker.entities().create(&long_reference_long_source).send().await?.done()?;
    let long_reference_short_source = Entity::builder()
        .id(long_reference_short_source_id.clone())
        .entity_type(long_reference_type.clone())
        .relationship("link", long_reference_target_id.clone())
        .build()?;
    broker.entities().create(&long_reference_short_source).send().await?.done()?;
    let retrieved = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .entities()
        .retrieve(&long_reference_long_source_id)
        .send()
        .await?;
    let entity = retrieved.body();
    expect_that!(
        entity,
        has_attribute("link", any_attribute().object(stop_zzibf4kcacb47hcyc8qc7zsg9yhlb6j13me23r7t_id.clone()))
    );
    let page = broker.with_accept(Accept::new(NgsiLdMediaType::Json)).entities().query().entity_type(&long_reference_type).locality(Locality::Local).ids(vec![long_reference_long_source_id.clone(), long_reference_short_source_id.clone()]).q(q::attr("link").eq(format!("urn:ngsi-ld:Stop:{namespace}-").as_str())).send().await?;
    expect_that!(page.items(), len(eq(1)));
    expect_that!(page.items(), nth(0, has_id(&long_reference_long_source_id)));
    let page_2 = broker.with_accept(Accept::new(NgsiLdMediaType::Json)).entities().query().entity_type(&long_reference_type).locality(Locality::Local).ids(vec![long_reference_long_source_id.clone(), long_reference_short_source_id.clone()]).q(q::attr("link").ne(format!("urn:ngsi-ld:Stop:{namespace}-").as_str())).send().await?;
    expect_that!(page_2.items(), len(eq(1)));
    expect_that!(page_2.items(), nth(0, has_id(&long_reference_short_source_id)));
    let page_3 = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .entities()
        .query()
        .entity_type(&long_reference_type)
        .locality(Locality::Local)
        .ids(vec![long_reference_long_source_id.clone(), long_reference_short_source_id.clone()])
        .q(q::attr("link").linked("name").eq("x"))
        .join(Join::Inline)
        .join_level(1.try_into()?)
        .send()
        .await?;
    expect_that!(page_3.items(), len(eq(1)));
    expect_that!(page_3.items(), nth(0, has_id(&long_reference_short_source_id)));
    Ok(())
}
